pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        uint256 amount = c.value();
        vm.deal(actor, amount);
        vm.prank(actor);
        c.getTokens();

        assertTrue(c.balanceOf(actor) == amount, "distributed tokens must be credited to recipient");
